package com.picalibrary.android;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.widget.*;
import java.util.*;

/** Optional E-H cookie-session setup. Public E-H browse remains account-free. */
public final class EhAccountActivity extends Activity {
    private EditText memberId,passHash,igneous,cfClearance;private TextView status;private boolean busy;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);Ui.applyWindow(this);render();}
    private Button button(String label,android.view.View.OnClickListener action){return Ui.button(this,label,action,false);}
    private EditText secret(String hint){EditText input=new EditText(this);input.setSingleLine(true);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);input.setHint(hint);input.setSaveEnabled(false);Ui.styleField(input,this);return input;}
    private void render(){EhAccountStore.Session session=EhAccountStore.load(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Ui.BG);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.addView(Ui.button(this,"‹ 返回",v->finish(),true));bar.addView(Ui.text(this,"E-H / ExH 账号",22,Ui.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);ScrollView scroll=new ScrollView(this);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(Ui.dp(this,18),Ui.dp(this,16),Ui.dp(this,18),Ui.dp(this,24));scroll.addView(p);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));p.addView(Ui.text(this,"公共 E-H 搜索、阅读、下载无需账号。这里的会话只用于 E-H 云收藏和 ExH 访问探测；不会保存 E-H 密码。",14,Ui.MUTED,false));p.addView(Ui.text(this,"先在官方站点登录，再复制身份 cookie。ipb_member_id 与 ipb_pass_hash 为必填；igneous / cf_clearance 仅在你的会话实际包含时填写。",12,Ui.MUTED,false));LinearLayout links=new LinearLayout(this);links.addView(button("官方登录页",v->open("https://forums.e-hentai.org/index.php?act=Login")),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(links,this,8);links.addView(button("官方注册页",v->open("https://forums.e-hentai.org/index.php?act=Reg&CODE=00")),new LinearLayout.LayoutParams(0,-2,1));p.addView(links);Ui.gap(p,this,12);Button sessionToggle=button("导入 / 更新会话 ▾",v->{android.view.View editor=p.findViewWithTag("eh-session-editor");if(editor!=null)editor.setVisibility(editor.getVisibility()==android.view.View.VISIBLE?android.view.View.GONE:android.view.View.VISIBLE);});p.addView(sessionToggle);LinearLayout editor=new LinearLayout(this);editor.setTag("eh-session-editor");editor.setOrientation(LinearLayout.VERTICAL);editor.setVisibility(android.view.View.GONE);p.addView(editor);editor.addView(Ui.text(this,"ipb_member_id",13,Ui.TEXT,true));memberId=new EditText(this);memberId.setSingleLine(true);memberId.setText(session.memberId);Ui.styleField(memberId,this);editor.addView(memberId);editor.addView(Ui.text(this,"ipb_pass_hash",13,Ui.TEXT,true));passHash=secret(session.passHash.isEmpty()?"必填":"已保存；留空则保留");editor.addView(passHash);editor.addView(Ui.text(this,"igneous（可选）",13,Ui.TEXT,true));igneous=secret(session.igneous.isEmpty()?"可选":"已保存；留空则保留");editor.addView(igneous);editor.addView(Ui.text(this,"cf_clearance（可选）",13,Ui.TEXT,true));cfClearance=secret(session.cfClearance.isEmpty()?"可选":"已保存；留空则保留");editor.addView(cfClearance);status=Ui.text(this,session.configured()?"E-H 会话已加密保存":"未配置会话；公共 E-H 功能仍可使用",13,Ui.MUTED,false);status.setPadding(0,Ui.dp(this,10),0,Ui.dp(this,8));p.addView(status);LinearLayout row1=new LinearLayout(this);row1.addView(button("保存并验证",v->saveAndVerify()),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(row1,this,8);row1.addView(button("同步云收藏",v->syncFavorites()),new LinearLayout.LayoutParams(0,-2,1));p.addView(row1);LinearLayout row2=new LinearLayout(this);row2.addView(button("探测 ExH",v->probe()),new LinearLayout.LayoutParams(0,-2,1));Ui.gap(row2,this,8);row2.addView(button("清除会话",v->clearSession()),new LinearLayout.LayoutParams(0,-2,1));p.addView(row2);p.addView(Ui.text(this,"会话字段使用 Android Keystore AES-GCM 加密；清除会话不会删除本地漫画、书架或最后一次同步到本机的收藏标记。",12,Ui.MUTED,false));setContentView(root);root.requestApplyInsets();}
    private void open(String url){startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}
    private EhAccountStore.Session candidate(){EhAccountStore.Session old=EhAccountStore.load(this);String id=memberId.getText().toString().trim();String hash=passHash.getText().toString().trim();String ign=igneous.getText().toString().trim();String cf=cfClearance.getText().toString().trim();return new EhAccountStore.Session(id.isEmpty()?old.memberId:id,hash.isEmpty()?old.passHash:hash,ign.isEmpty()?old.igneous:ign,cf.isEmpty()?old.cfClearance:cf);}
    private void saveAndVerify(){if(busy)return;EhAccountStore.Session old=EhAccountStore.load(this),next=candidate();if(!next.configured()){status.setText("请填写 ipb_member_id 和 ipb_pass_hash");return;}busy=true;status.setText("正在验证 E-H 会话…");new Thread(()->{try{EhAccountStore.save(this,next);new EhClient(this).verifyAccount();runOnUiThread(()->{busy=false;passHash.setText("");igneous.setText("");cfClearance.setText("");status.setText("E-H 会话有效，已用 Android Keystore 加密保存。");});}catch(Exception e){try{if(old.configured())EhAccountStore.save(this,old);else EhAccountStore.clear(this);}catch(Exception ignored){}runOnUiThread(()->{busy=false;status.setText("验证失败："+(e.getMessage()==null?"会话不可用":e.getMessage()));});}}).start();}
    private void syncFavorites(){if(busy)return;if(!EhAccountStore.load(this).configured()){status.setText("请先保存并验证 E-H 会话");return;}busy=true;status.setText("正在同步 E-H 云收藏…");new Thread(()->{try{List<EhClient.Comic> comics=new EhClient(this).favoritesAll();UnifiedEhCatalogSync.mergeAll(this,comics);EhFavoriteStore.replaceRemote(this,comics);runOnUiThread(()->{busy=false;status.setText("E-H 云收藏已同步："+comics.size()+" 本");});}catch(Exception e){runOnUiThread(()->{busy=false;status.setText("同步失败："+(e.getMessage()==null?"未知错误":e.getMessage()));});}}).start();}
    private void probe(){if(busy)return;busy=true;status.setText("正在探测 ExH…");new Thread(()->{String value=new EhClient(this).probeExH();runOnUiThread(()->{busy=false;status.setText("ExH: "+value);});}).start();}
    private void clearSession(){if(busy)return;EhAccountStore.clear(this);passHash.setText("");igneous.setText("");cfClearance.setText("");status.setText("E-H 会话已清除；公共功能与本地数据不受影响");}
}
